import React from 'react';

const Navbar = () => {
  return (
    <header className="fixed top-0 left-0 right-0 z-[999] h-20 bg-white/90 backdrop-blur-xl border-b border-slate-200 shadow-xl">
      <div className="max-w-7xl mx-auto h-full px-6 flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div className="w-11 h-11 rounded-lg bg-gradient-to-r from-indigo-600 to-fuchsia-500 text-white grid place-items-center font-black text-lg tracking-tight">U</div>
          <div>
            <h1 className="text-xl font-black text-slate-900 leading-none">MediCampus</h1>
            <p className="text-xs text-slate-500">Healthcare System</p>
          </div>
        </div>

        <nav className="flex items-center gap-8 text-sm font-semibold text-slate-700 tracking-wide">
          <a href="#home" className="hover:text-indigo-600 transition">Home</a>
          <a href="#features" className="hover:text-indigo-600 transition">Features</a>
          <a href="#dashboard" className="hover:text-indigo-600 transition">Dashboard</a>
          <a href="#contact" className="hover:text-indigo-600 transition">Contact</a>
          <a href="#" className="px-5 py-2 bg-indigo-600 text-white rounded-xl shadow-md hover:bg-indigo-500 transition">Book Appointment</a>
        </nav>

        <button className="hidden lg:inline-flex px-4 py-2 rounded-xl bg-indigo-600 text-white font-semibold hover:bg-indigo-500 transition">Menu</button>
      </div>
    </header>
  );
};

export default Navbar;
